from decimal import Decimal, InvalidOperation
from typing import Any


_ZERO = Decimal("0")
_EIGHT_TENTHS = Decimal("8") / Decimal("10")


def _number(value: Any) -> Decimal:
    """Convert legacy numeric values, with empty or missing values treated as zero."""
    if value is None or value == "":
        return _ZERO
    if isinstance(value, Decimal):
        return value
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return _ZERO


def _is_live(row: dict) -> bool:
    return row.get("DEL_FLG") != "Y"


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the legacy credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    eligible_indexes = [
        index
        for index, account in enumerate(accounts)
        if _is_live(account) and account.get("ACCT_TYP") == "C"
    ]
    eligible_indexes.sort(key=lambda index: accounts[index].get("ACCT_ID"))

    for index in eligible_indexes:
        account = accounts[index]
        acct_id = account.get("ACCT_ID")

        exposure = _ZERO
        for order in orders:
            if (
                _is_live(order)
                and order.get("ACCT_ID") == acct_id
                and order.get("STAT_CD") == "I"
            ):
                exposure += _number(order.get("TOT_AMT"))

        limit = _number(account.get("CRED_LIMIT"))
        held = account.get("CRED_HOLD") == "Y"

        if exposure > limit and not held:
            new_accounts[index]["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))
            held = True

        if exposure <= limit * _EIGHT_TENTHS and held:
            new_accounts[index]["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
